cd "C:<HELM_ROOT>" && cat > "$TEMP/claude_valscan.py" <<'EOF'
import json,re,sys,os,subprocess
src=sys.argv[1]
raw=open(src,encoding='utf-8').read()
vals=set()
for m in re.finditer(r'\\"([A-Z][A-Z0-9_]{2,})\\":\\"(.*?)\\"',raw):
    k,v=m.group(1),m.group(2)
    if len(v)>=6 and any(s in k for s in ('PASSWORD','TOKEN','KEY','SECRET')): vals.add(v)
print("secret-like values extracted:",len(vals))
files=subprocess.run(['git','ls-files','--others','--exclude-standard'],capture_output=True,text=True).stdout.split('\n')
files+=subprocess.run(['git','diff','--name-only'],capture_output=True,text=True).stdout.split('\n')
hits={}
for f in filter(None,files):
    try: t=open(f,encoding='utf-8',errors='ignore').read()
    except Exception: continue
    n=sum(t.count(v) for v in vals)
    if n: hits[f]=n
for f,n in sorted(hits.items()): print(n,f)
EOF
